45	// ── Security: Rate limiting (in-memory, simple) ──────────────────────────────
46	const rateLimitMap = new Map();
47	const RATE_LIMIT_WINDOW = 60_000; // 1 minute
48	const RATE_LIMITS = {
49	  heavy: 10,   // AI chat, orchestration runs, playground — 10/min
50	  write: 60,   // file writes, creates, deletes — 60/min
51	  read: 200,   // reads, listings — 200/min
52	};
53	
54	function rateLimit(tier) {
55	  const max = RATE_LIMITS[tier] || RATE_LIMITS.read;
56	  return (req, res, next) => {
57	    const key = `${tier}:${req.ip}`;
58	    const now = Date.now();
59	    let entry = rateLimitMap.get(key);
60	    if (!entry || now - entry.start > RATE_LIMIT_WINDOW) {
61	      entry = { start: now, count: 0 };
62	      rateLimitMap.set(key, entry);
63	    }
64	    entry.count++;
65	    if (entry.count > max) {
66	      return res.status(429).json({ error: `Rate limit exceeded (${max}/${RATE_LIMIT_WINDOW / 1000}s)` });
67	    }
68	    next();
69	  };
70	}
71	
72	// Cleanup stale entries every 5 minutes
73	setInterval(() => {
74	  const now = Date.now();
75	  for (const [key, entry] of rateLimitMap) {
76	    if (now - entry.start > RATE_LIMIT_WINDOW * 2) rateLimitMap.delete(key);
77	  }
78	}, 300_000);
