151	// --- Config Management ---
152	function loadConfig() {
153	  try {
154	    if (fs.existsSync(CONFIG_PATH)) {
155	      const raw = JSON.parse(fs.readFileSync(CONFIG_PATH, 'utf-8'));
156	      // Validate structure
157	      if (!raw || typeof raw !== 'object') return { projectDirs: [] };
158	      if (!Array.isArray(raw.projectDirs)) raw.projectDirs = [];
159	      // Ensure all entries are strings
160	      raw.projectDirs = raw.projectDirs.filter(d => typeof d === 'string');
161	      return raw;
162	    }
163	  } catch {}
164	  return { projectDirs: [] };
165	}
