183	function parseAgent(filePath) {
184	  try {
185	    const content = fs.readFileSync(filePath, 'utf-8');
186	    const { data, content: body } = matter(content);
187	    const stats = fs.statSync(filePath);
188	    return {
189	      filename: path.basename(filePath, '.md'),
190	      path: filePath,
191	      frontmatter: data,
192	      name: data.name || path.basename(filePath, '.md'),
193	      description: data.description || '',
194	      model: data.model || '',
195	      tools: data.tools || '',
196	      body: body.trim(),
197	      raw: content,
198	      updatedAt: stats.mtime.toISOString(),
199	    };
200	  } catch (e) {
201	    return null;
202	  }
203	}
