205	function listAgents(dir) {
206	  try {
207	    if (!fs.existsSync(dir)) return [];
208	    return fs.readdirSync(dir)
209	      .filter(f => f.endsWith('.md'))
210	      .map(f => parseAgent(path.join(dir, f)))
211	      .filter(Boolean);
212	  } catch {
213	    return [];
214	  }
