217	function listMdFiles(dir) {
218	  try {
219	    if (!fs.existsSync(dir)) return [];
220	    return fs.readdirSync(dir)
221	      .filter(f => f.endsWith('.md'))
222	      .map(f => {
223	        const filePath = path.join(dir, f);
224	        const content = readFileSafe(filePath);
225	        const stats = fs.statSync(filePath);
226	        return {
227	          name: f.replace('.md', ''),
228	          content: content || '',
229	          path: filePath,
230	          updatedAt: stats.mtime.toISOString(),
231	        };
232	      });
233	  } catch {
234	    return [];
235	  }
236	}
