352	function discoverProjects(dirs) {
353	  const projects = [];
354	  for (const dir of dirs) {
355	    const resolved = dir.replace(/^~/, HOME);
356	    if (!fs.existsSync(resolved)) continue;
357	    try {
358	      const entries = fs.readdirSync(resolved, { withFileTypes: true });
359	      for (const entry of entries) {
360	        if (!entry.isDirectory()) continue;
361	        if (entry.name.startsWith('.') || entry.name === 'node_modules') continue;
362	        const projectPath = path.join(resolved, entry.name);
363	        const hasClaudeDir = fs.existsSync(path.join(projectPath, '.claude'));
364	        const hasClaudeMd = fs.existsSync(path.join(projectPath, 'CLAUDE.md'));
365	        const hasPackageJson = fs.existsSync(path.join(projectPath, 'package.json'));
366	        const hasPubspec = fs.existsSync(path.join(projectPath, 'pubspec.yaml'));
367	        if (hasClaudeDir || hasClaudeMd || hasPackageJson || hasPubspec) {
368	          const agents = listAgents(path.join(projectPath, '.claude', 'agents'));
369	          const commands = listMdFiles(path.join(projectPath, '.claude', 'commands'));
370	          const rules = listMdFiles(path.join(projectPath, '.claude', 'rules'));
371	          projects.push({
372	            id: Buffer.from(projectPath).toString('base64url'),
373	            name: entry.name,
374	            path: projectPath,
375	            displayPath: projectPath.replace(HOME, '~'),
376	            hasClaudeDir,
377	            hasClaudeMd,
378	            agentCount: agents.length,
379	            commandCount: commands.length,
380	            ruleCount: rules.length,
381	            agents,
382	            commands: commands.map(c => c.name),
383	            rules: rules.map(r => r.name),
384	          });
385	        }
386	      }
387	    } catch {}
388	  }
389	  return projects;
390	}
