1428	// Topological sort helper
1429	function topoSort(nodes, edges) {
1430	  const inDegree = {};
1431	  const adj = {};
1432	  for (const n of nodes) { inDegree[n.id] = 0; adj[n.id] = []; }
1433	  for (const e of edges) {
1434	    adj[e.source].push(e.target);
1435	    inDegree[e.target] = (inDegree[e.target] || 0) + 1;
1436	  }
1437	  const queue = nodes.filter(n => inDegree[n.id] === 0).map(n => n.id);
1438	  const order = [];
1439	  while (queue.length) {
1440	    const id = queue.shift();
1441	    order.push(id);
1442	    for (const next of adj[id]) {
1443	      inDegree[next]--;
1444	      if (inDegree[next] === 0) queue.push(next);
1445	    }
1446	  }
1447	  return order;
1448	}
