### Feature 5: Orchestration Retry/Conditional Logic

**Backend changes in `server.js`:**

Modify the orchestration execution loop in `/api/orchestrations/run` (lines 1516-1568). Currently the loop is:

```js
for (const nodeId of order) {
  // ...build prompt...
  try {
    const output = await runClaudeSync(prompt);
    // ...
  } catch (err) {
    runStatus = 'failed';
    send({ type: 'error', ... });
    break;
  }
}
```

Replace with retry + condition logic:

```js
for (const nodeId of order) {
  const node = nodeMap[nodeId];
  if (!node) continue;
  if (node.data?.isStart) { /* existing logic */ continue; }

  // Condition check: if node has a condition, check previous node output
  const condition = node.data?.condition;
  if (condition) {
    const incomingEdges = (edges || []).filter(e => e.target === nodeId);
    const prevOutputs = incomingEdges.map(e => results[e.source] || '').join('\n');
    if (!prevOutputs.includes(condition)) {
      results[nodeId] = `[SKIPPED: condition "${condition}" not matched]`;
      send({ type: 'skipped', nodeId, label: nodeLabel, condition });
      continue;
    }
  }

  // Retry logic
  const maxRetries = Math.min(node.data?.retryCount || 0, 3);
  let attempt = 0;
  let lastError = null;
  let output = null;

  while (attempt <= maxRetries) {
    try {
      if (attempt > 0) send({ type: 'retry', nodeId, label: nodeLabel, attempt });
      output = await runClaudeSync(prompt);
      break;
    } catch (err) {
      lastError = err;
      attempt++;
    }
  }

  if (output !== null) {
    results[nodeId] = output;
    lastOutput = output;
    send({ type: 'done', nodeId, label: nodeLabel, output });
  } else {
    runStatus = 'failed';
    send({ type: 'error', nodeId, label: nodeLabel, error: lastError.message, retries: maxRetries });
    break;
  }
}
```

