**In-memory cron job map:**
```js
const activeJobs = new Map(); // id -> cron.ScheduledTask

function startScheduleJob(schedule) {
  if (activeJobs.has(schedule.id)) activeJobs.get(schedule.id).stop();
  if (!schedule.enabled || !cron.validate(schedule.cron)) return;

  const job = cron.schedule(schedule.cron, async () => {
    const startTime = Date.now();
    try {
      const output = await runClaudeSync(
        /* build prompt same as playground */
        buildScheduledPrompt(schedule),
        300000 // 5 min timeout for scheduled runs
      );
      logAgentRun({
        agentName: schedule.agentName,
        prompt: schedule.prompt.slice(0, 200),
        source: 'schedule',
        status: 'success',
        duration: Date.now() - startTime,
        promptChars: schedule.prompt.length,
        outputChars: output.length,
        metadata: { scheduleId: schedule.id }
      });
      // Update lastRun info
      const schedules = loadSchedules();
      const idx = schedules.findIndex(s => s.id === schedule.id);
      if (idx >= 0) {
        schedules[idx].lastRunAt = new Date().toISOString();
        schedules[idx].lastRunStatus = 'success';
        saveSchedules(schedules);
      }
    } catch (err) {
      logAgentRun({ ...same, status: 'error', error: err.message });
    }
  });

  activeJobs.set(schedule.id, job);
}
```

**On server startup** (after the `app.listen` block, line 2801):
```js
// Restore scheduled jobs
try {
  const schedules = loadSchedules();
  for (const s of schedules) {
    if (s.enabled) startScheduleJob(s);
  }
} catch {}
```

